    "name": "Remanent magnetization",
    "symbol": "\\\\mathbf M_r",
    "symbol_text": "Mᵣ",
    "units": "\\\\mathrm{A\\\\,m^{-1}}",
    "value_type": "vector",
    "spatial": true,
    "category": "mineral_property",
    "layer": 1,
    "description": "SOURCE_FACT — Magnetization retained independently of the present inducing field; not recoverable from scalar susceptibility alone.",
    "directly_observable": false,
